-- Module: admission — Admissions

CREATE SCHEMA IF NOT EXISTS admission;
COMMENT ON SCHEMA admission IS 'Admissions: Admission cycles, fees, applications with applicant, guardian and emergency-contact details, through to student creation.';

CREATE TABLE admission.admission_cycle (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid NOT NULL,
    name varchar(150) NOT NULL,
    admission_basis varchar(30) NOT NULL DEFAULT  'course',
    program_id uuid,
    course_id uuid,
    grade_level_id uuid,
    academic_year_id uuid,
    academic_term_id uuid,
    start_date date NOT NULL,
    end_date date,
    min_applications integer,
    max_applications integer,
    minimum_age_years integer,
    application_fee_head_id uuid,
    status varchar(30) NOT NULL DEFAULT  'draft',
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_admission_cycle PRIMARY KEY (id),
    CONSTRAINT ck_admission_cycle_admission_basis CHECK (admission_basis IN ('program', 'course', 'grade_level')),
    CONSTRAINT ck_admission_cycle_status CHECK (status IN ('draft', 'confirmed', 'open', 'admission', 'closed', 'cancelled')),
    CONSTRAINT ck_admission_cycle_1 CHECK (end_date IS NULL OR end_date >= start_date),
    CONSTRAINT uq_admission_cycle_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE admission.admission_cycle IS 'An admission window for a program, course or grade in an academic year.';
COMMENT ON COLUMN admission.admission_cycle.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
