ALTER TABLE admission.application FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON admission.application USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE admission.application_emergency_contact ENABLE ROW LEVEL SECURITY;
ALTER TABLE admission.application_emergency_contact FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON admission.application_emergency_contact USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
