-- === Module-local infrastructure (distributed deployment: no cross-schema access) ===
CREATE TABLE admission.idempotency_key (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    user_id uuid,
    operation_name varchar(120) NOT NULL,
    request_hash varchar(64),
    response_status smallint,
    response_body text,
    locked_at timestamptz,
    completed_at timestamptz,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_admission_idempotency_key PRIMARY KEY (id),
    CONSTRAINT uq_admission_idempotency_key_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE admission.idempotency_key IS 'Module-local idempotency store of the admission module: stored outcome of a write carrying an Idempotency-Key; replays return the stored response. Rows expire after 24h (cleanup job).';
COMMENT ON COLUMN admission.idempotency_key.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN admission.idempotency_key.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN admission.idempotency_key.idempotency_key IS 'Key sent by the client.';
COMMENT ON COLUMN admission.idempotency_key.user_id IS 'Caller.';
COMMENT ON COLUMN admission.idempotency_key.operation_name IS 'Operation the key was used on.';
COMMENT ON COLUMN admission.idempotency_key.request_hash IS 'Hash of the request body; a replay with a different body is rejected.';
COMMENT ON COLUMN admission.idempotency_key.response_status IS 'Stored HTTP status.';
COMMENT ON COLUMN admission.idempotency_key.response_body IS 'Stored response body.';
COMMENT ON COLUMN admission.idempotency_key.locked_at IS 'Set while the first attempt is still executing.';
COMMENT ON COLUMN admission.idempotency_key.completed_at IS 'When the stored response was written.';
COMMENT ON COLUMN admission.idempotency_key.expires_at IS 'When the row may be purged.';
COMMENT ON COLUMN admission.idempotency_key.created_at IS 'Row creation time.';
COMMENT ON COLUMN admission.idempotency_key.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN admission.idempotency_key.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN admission.idempotency_key.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN admission.idempotency_key.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN admission.idempotency_key.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE admission.idempotency_key ENABLE ROW LEVEL SECURITY;
ALTER TABLE admission.idempotency_key FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON admission.idempotency_key USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE admission.operation (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    operation_name varchar(120) NOT NULL,
    resource_type varchar(80),
    resource_id uuid,
    status varchar(20) NOT NULL DEFAULT 'running',
    progress_percent smallint,
    error_code varchar(60),
    error_message varchar(500),
    result_entity_type varchar(80),
    result_entity_id uuid,
    started_by_user_id uuid,
    started_at timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_admission_operation PRIMARY KEY (id),
    CONSTRAINT ck_admission_operation_status CHECK (status IN ('running', 'succeeded', 'failed', 'cancelled'))
);
COMMENT ON TABLE admission.operation IS 'Module-local long-running operation record of the admission module, returned by its async API calls; polled by clients until it finishes.';
COMMENT ON COLUMN admission.operation.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN admission.operation.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN admission.operation.operation_name IS 'Operation id as exposed by the API (module.Method).';
COMMENT ON COLUMN admission.operation.resource_type IS 'Kind of resource being worked on.';
COMMENT ON COLUMN admission.operation.resource_id IS 'Id of that resource.';
COMMENT ON COLUMN admission.operation.status IS 'running / succeeded / failed / cancelled.';
COMMENT ON COLUMN admission.operation.progress_percent IS 'Progress, when the job reports it.';
COMMENT ON COLUMN admission.operation.error_code IS 'Machine error code when failed.';
COMMENT ON COLUMN admission.operation.error_message IS 'Human error summary when failed.';
COMMENT ON COLUMN admission.operation.result_entity_type IS 'Kind of the produced record.';
COMMENT ON COLUMN admission.operation.result_entity_id IS 'Id of the produced record.';
COMMENT ON COLUMN admission.operation.started_by_user_id IS 'User who started it.';
COMMENT ON COLUMN admission.operation.started_at IS 'Start time.';
COMMENT ON COLUMN admission.operation.finished_at IS 'End time.';
COMMENT ON COLUMN admission.operation.created_at IS 'Row creation time.';
COMMENT ON COLUMN admission.operation.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN admission.operation.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN admission.operation.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN admission.operation.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN admission.operation.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE admission.operation ENABLE ROW LEVEL SECURITY;
ALTER TABLE admission.operation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON admission.operation USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE admission.number_sequence (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid,
    sequence_code varchar(40) NOT NULL,
    period_key varchar(20) NOT NULL DEFAULT '',
    prefix varchar(20),
    padding smallint NOT NULL DEFAULT 6,
    next_value bigint NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_admission_number_sequence PRIMARY KEY (id),
    CONSTRAINT uq_admission_number_sequence_1 UNIQUE NULLS NOT DISTINCT (tenant_id, institution_id, sequence_code, period_key)
);
COMMENT ON TABLE admission.number_sequence IS 'Module-local gap-aware number source of the admission module (application numbers). Read with SELECT ... FOR UPDATE inside the issuing transaction; never shared with another module.';
COMMENT ON COLUMN admission.number_sequence.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN admission.number_sequence.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN admission.number_sequence.institution_id IS 'Institution scope (NULL = tenant-wide sequence).';
COMMENT ON COLUMN admission.number_sequence.sequence_code IS 'Which number series of this module (application numbers).';
COMMENT ON COLUMN admission.number_sequence.period_key IS 'Reset period (fiscal year key such as FY2026; empty = never resets).';
COMMENT ON COLUMN admission.number_sequence.prefix IS 'Rendered number prefix.';
COMMENT ON COLUMN admission.number_sequence.padding IS 'Zero padding width of the numeric part.';
COMMENT ON COLUMN admission.number_sequence.next_value IS 'Next number to issue.';
COMMENT ON COLUMN admission.number_sequence.created_at IS 'Row creation time.';
COMMENT ON COLUMN admission.number_sequence.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN admission.number_sequence.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN admission.number_sequence.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN admission.number_sequence.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN admission.number_sequence.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE admission.number_sequence ENABLE ROW LEVEL SECURITY;
ALTER TABLE admission.number_sequence FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON admission.number_sequence USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE INDEX ix_number_sequence_institution_id ON admission.number_sequence (institution_id);

